import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class BottleneckBlock(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, skip: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = make_conv1(inplanes, planes)
        self.norm1 = norm_layer(planes)
        self.conv_b = make_conv3(planes, planes, stride)
        self.norm2 = norm_layer(planes)
        self.conv_c = make_conv1(planes, planes * self.expansion)
        self.norm3 = norm_layer(planes * self.expansion)
        self.skip = skip
        self.stride = stride

    def forward(self, input: Tensor) -> Tensor:
        identity = input

        y = self.conv_a(input)
        y = self.norm1(y)
        y = F.hardswish(y, inplace=True)
        y = self.conv_b(y)
        y = self.norm2(y)
        y = F.hardswish(y, inplace=True)
        y = self.conv_c(y)
        y = self.norm3(y)

        if self.skip is not None:
            identity = self.skip(input)

        y = y + identity
        y = F.hardswish(y, inplace=True)
        return y


class ConvStem(nn.Module):
    def __init__(self, in_chs, out_chs, norm_layer=nn.BatchNorm2d):
        super().__init__()
        self.conv = nn.Conv2d(in_chs, out_chs, kernel_size=3, stride=2, padding=1, bias=False)
        self.norm = norm_layer(out_chs)
        self.act = nn.Hardswish(inplace=True)


    def forward(self, x):
        x = self.conv(x)
        x = self.norm(x)
        x = self.act(x)

        return x


class NetStage(nn.Module):
    def __init__(self, planes, n, stride, in_ch, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        blocks = []
        downsample = None
        if stride != 1 or in_ch != planes * BottleneckBlock.expansion:
            downsample = nn.Sequential(
                make_conv1(in_ch, planes * BottleneckBlock.expansion, stride),
                norm_layer(planes * BottleneckBlock.expansion),
            )
        blocks.append(BottleneckBlock(in_ch, planes, stride, downsample))
        in_ch = planes * BottleneckBlock.expansion
        for _ in range(1, n):
            blocks.append(BottleneckBlock(in_ch, planes))
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)


class Head(nn.Module):
    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()

        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits: bool = False):
        x = x.mean((2, 3), keepdim=True)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)


class Network(nn.Module):
    def __init__(self, settings, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = ConvStem(in_chans, 16, norm_layer=norm_layer)
        in_ch = 16
        stages = []
        for idx, (planes, n, stride) in enumerate(settings):
            stage = NetStage(planes, n, stride, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.Sequential(*stages)
        self.head = Head(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, input):
        input = self.stem(input)
        input = self.stages(input)
        return input

    def forward_head(self, input, pre_logits: bool = False):
        return self.head(input, pre_logits=pre_logits)

    def forward(self, input):
        input = self.forward_features(input)
        input = self.forward_head(input)
        return input


def _network(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 2, 1), (16, 3, 2), (32, 2, 2)]}
    model = Network(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def build_model(weights=None, progress=True, **kwargs):
    return _network('small', weights, progress, **kwargs)


